int get_sock_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer) {
    struct atm_vcc *vcc;

    if (!sock || !sockaddr || !sockaddr_len)
        return -ENOTCONN;

    vcc = (struct atm_vcc *)sock->sk;

    if (!vcc || !test_bit(ATM_VF_CONNECTED, &vcc->flags))
        return -ENOTCONN;

    ((struct sockaddr_atmpvc *)sockaddr)->sat_family = AF_ATMPVC;
    ((struct sockaddr_atmpvc *)sockaddr)->sat_number = vcc->local.number;
    ((struct sockaddr_atmpvc *)sockaddr)->sat_vpi = htons(vcc->local.vpi);
    ((struct sockaddr_atmpvc *)sockaddr)->sat_vci = htons(vcc->local.vci);
    *sockaddr_len = sizeof(struct sockaddr_atmpvc);

    return 0;
}

int get_socket_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer) {
    struct atm_vcc *vcc;

    if (!sock || !sockaddr || !sockaddr_len)
        return -ENOTCONN;

    vcc = ATM-marshall_vcc(sock);
    if (!vcc || !vcc->vci || !vcc->vpi)
        return -ENOTCONN;

    memset(sockaddr, 0, sizeof(struct sockaddr));
    ((struct sockaddr_atm *)sockaddr)->sat_family = AF_ATMPVC;
    ((struct sockaddr_atm *)sockaddr)->sat_addr.itf = vcc->dev ? vcc->dev->number : 0;
    ((struct sockaddr_atm *)sockaddr)->sat_addr.vpi = vcc->vpi;
    ((struct sockaddr_atm *)sockaddr)->sat_addr.vci = vcc->vci;

    *sockaddr_len = sizeof(struct sockaddr_atm);
    return 0;
}

int get_sock_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer) {
    struct atm_vcc *vcc = sock->sk->sk_user_data;

    if (!vcc || !vcc->vc.connected) {
        return -ENOTCONN;
    }

    struct sockaddr_atm *atm_addr = (struct sockaddr_atm *)sockaddr;
    atm_addr->salem = 0;
    atm_addr->addr.itf = vcc->dev->number;
    atm_addr->addr.vpi = vcc->tp->vpi;
    atm_addr->addr.vci = vcc->tp->vci;
    atm_addr->address_family = AF_ATMPVC;

    *sockaddr_len = sizeof(struct sockaddr_atm);
    return 0;
}

int get_socket_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer)
{
    struct atm_vcc *vcc = sock->sk.atm_vcc;
    struct sockaddr_atmpvc *atmpvc = (struct sockaddr_atmpvc *)sockaddr;

    if (!vcc || vcc->vci == ATM_VCI_UNSPEC) {
        return -ENOTCONN;
    }

    atmpvc->sap_family = AF_ATMPVC;
    atmpvc->address.itf = vcc->dev->number;
    atmpvc->address.vpi = vcc->vpi;
    atmpvc->address.vci = vcc->vci;

    *sockaddr_len = sizeof(*atmpvc);
    return 0;
}

int get_socket_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer) {
    struct atm_vcc *vcc = sock->sk->sk_user_data;

    if (!vcc || (peer && !vcc->remote) || (!peer && !vcc->local)) {
        return -ENOTCONN;
    }

    struct sockaddr_atm *atm_addr = (struct sockaddr_atm *)sockaddr;
    atm_addr->sac_family = AF_ATMPVC;
    atm_addr->sac_type = ATM_ADDR_PVC;

    if (peer) {
        atm_addr->sac_addr.itf = vcc->remote->entry.itf;
        atm_addr->sac_addr.vpi = vcc->remote->entry.vpi;
        atm_addr->sac_addr.vci = vcc->remote->entry.vci;
    } else {
        atm_addr->sac_addr.itf = vcc->local->entry.itf;
        atm_addr->sac_addr.vpi = vcc->local->entry.vpi;
        atm_addr->sac_addr.vci = vcc->local->entry.vci;
    }

    *sockaddr_len = sizeof(struct sockaddr_atm);
    return 0;
}
